    "messageEnterDifferentName": MessageLookupByLibrary.simpleMessage(
      "தயவுசெய்து வேறு பெயரை உள்ளிடவும்",
    ),
    "messageEntryAlreadyExist": m4,
    "messageEntryTypeDefault": MessageLookupByLibrary.simpleMessage(
      "ஒரு நுழைவு",
    ),
    "messageEntryTypeFile": MessageLookupByLibrary.simpleMessage("ஒரு கோப்பு"),
    "messageEntryTypeFolder": MessageLookupByLibrary.simpleMessage(
      "ஒரு கோப்புறை",
    ),
    "messageEqValuesP1": MessageLookupByLibrary.simpleMessage(
      "அடிப்படை உரிமைகள் மற்றும் அடிப்படை சுதந்திரங்கள் உள்ளார்ந்தவை, மாற்ற முடியாதவை மற்றும் அனைவருக்கும் சமமாக பொருந்தும். மனித உரிமைகள் உலகளாவியவை; பன்னாட்டு சட்டத்தில் பாதுகாக்கப்பட்டு, பொறிக்கப்பட்டுள்ளது ",
    ),
    "messageEqValuesP10": MessageLookupByLibrary.simpleMessage(
      "ஒரு அமைப்பாக, நாங்கள் எங்கள் கொள்கைகள் மற்றும் நடைமுறைகளுடன் வெளிப்படையாக இருக்க முற்படுகிறோம். முடிந்தவரை, எங்கள் மூலக் குறியீடு திறந்த மற்றும் இலவசமாக கிடைக்கிறது, இது சமூகத்தால் இயக்கப்படும் வளர்ச்சி, பகிர்வு மற்றும் இந்த கொள்கைகளின் பரப்புதலை ஊக்குவிக்கும் உரிமங்களால் பாதுகாக்கப்படுகிறது",
    ),
    "messageEqValuesP11": MessageLookupByLibrary.simpleMessage(
      "தன்னை சுதந்திரமாக வெளிப்படுத்தவும், பொதுத் தகவல்களை அணுகவும் ஒரு உண்மையான சனநாயகத்தின் முதுகெலும்பாகும். பொது தகவல்கள் பொது களத்தில் இருக்க வேண்டும். கருத்துச் சுதந்திரத்தில் செயலில் மற்றும் சூடான விவாதம் அடங்கும், வாதங்கள் கூட வெளிப்படையாக வெளிப்படுத்தப்பட்டவை, மோசமாக கட்டமைக்கப்பட்டுள்ளன, மேலும் அவை சிலருக்கு ஆபத்தானதாக கருதப்படலாம். இருப்பினும், கருத்துச் விடுதலை ஒரு முழுமையான உரிமை அல்ல. வன்முறை மற்றும் மற்றவர்களின் உரிமைகளை மீறுவதற்கான தூண்டுதலுக்கு எதிராக நாங்கள் உறுதியாக நிற்கிறோம், குறிப்பாக வன்முறை, வெறுப்பு, பாகுபாடு மற்றும் எந்தவொரு அடையாளம் காணக்கூடிய இன அல்லது சமூகக் குழுவையும் பரப்புதல்",
    ),
    "messageEqValuesP12": MessageLookupByLibrary.simpleMessage(
      "நாங்கள் வெவ்வேறு நாடுகளிலிருந்து செயல்படுகிறோம் மற்றும் பல்வேறு சமூக பின்னணியிலிருந்து வருகிறோம். உடல் மற்றும் டிசிட்டல் உலகில் மற்றவர்களின் உரிமைகளை மதிக்கும் மற்றும் பாதுகாக்கும் ஒரு சமூகத்தை நோக்கி நாங்கள் ஒன்றிணைந்து செயல்படுகிறோம். பன்னாட்டு உரிமைகள் மசோதா எங்கள் வேலையை ஊக்குவிக்கும் மனித உரிமைகளின் தொகுப்பை வெளிப்படுத்துகிறது; இந்த உரிமைகளைப் பாதுகாக்க மக்களுக்கு உரிமையும் கடமையும் இருப்பதாக நாங்கள் நம்புகிறோம்",
    ),
    "messageEqValuesP13": MessageLookupByLibrary.simpleMessage(
      "இந்த கொள்கைகளையும் எங்கள் பணி விதிமுறைகளையும் மீறுவதற்கு எங்கள் கருவிகள் மற்றும் சேவைகள் தீய பயன்பாடு செய்யப்படலாம் என்பதை நாங்கள் புரிந்துகொள்கிறோம், மேலும் அத்தகைய பயன்பாட்டை நாங்கள் உறுதியாகவும் தீவிரமாகவும் கண்டிக்கிறோம், தடைசெய்கிறோம். சட்டவிரோத நடவடிக்கைகளின் கமிசனை மேலும் மேம்படுத்த எங்கள் மென்பொருள் மற்றும் சேவைகளை நாங்கள் பயன்படுத்த அனுமதிக்கவில்லை, வெறுக்கத்தக்க பேச்சைப் பரப்புவதற்கும் அல்லது இணையம் மூலம் வன்முறையை மேம்படுத்துவதற்கும் நாங்கள் உதவ மாட்டோம்",
    ),
    "messageEqValuesP14": MessageLookupByLibrary.simpleMessage(
      "எங்கள் தயாரிப்புகள் மற்றும் சேவைகளின் தவறான பயன்பாட்டைத் தணிக்க பாதுகாப்புகளை நாங்கள் வைத்திருக்கிறோம். எங்கள் கொள்கைகள் அல்லது பணி விதிமுறைகளை மீறும் எந்தவொரு பயன்பாட்டையும் நாம் அறிந்திருக்கும்போது, அதைத் தடுக்க நாங்கள் நடவடிக்கை எடுக்கிறோம். எங்கள் உள் கொள்கைகளால் வழிநடத்தப்பட்டு, எங்கள் கொள்கைகளை வேறுபாடின்மை செய்யக்கூடிய செயல்களை நாங்கள் கவனமாக வேண்டுமென்றே ஆலோசிக்கிறோம். எங்கள் தயாரிப்புகள் மற்றும் சேவைகளுக்குத் திறந்த அணுகலை செயல்படுத்துவதற்கும், எங்கள் கொள்கைகளை நிலைநிறுத்துவதற்கும் இடையே சரியான சமநிலையை அடைய முடியும் என்பதற்காக எங்கள் நடைமுறைகள் பட்டறிவு மற்றும் சிறந்த நடைமுறைகளின் அடிப்படையில் தொடர்ந்து உருவாகின்றன",
    ),
    "messageEqValuesP2": MessageLookupByLibrary.simpleMessage(
      "துணிச்சலான மக்கள் மனித உரிமைகளைப் பாதுகாக்கவும், அணிதிரட்டவும், விமர்சிக்கவும் மற்றும் துச்பிரயோகத்தில் ஈடுபட்டவர்களை அம்பலப்படுத்தவும் உயிரையும் சுதந்திரத்தையும் அபாயப்படுத்துகிறார்கள். துணிச்சலானவர்கள் மற்றவர்களுக்கு ஆதரவளிக்கவும், யோசனைகளுக்காகவும், தங்கள் கவலைகளை உலகத்துடன் தொடர்புகொள்வதையும் குரல் கொடுக்கிறார்கள். இந்த துணிச்சலான மக்கள் தங்கள் மனித உரிமைகளை ஆன்லைனில் பயன்படுத்துகிறார்கள்",
    ),
    "messageEqValuesP3": MessageLookupByLibrary.simpleMessage(
      "இணையம் இலவச வெளிப்பாடு மற்றும் சுயநிர்ணயத்திற்கான ஒரு தளமாகும். எந்தவொரு தகவல்தொடர்பு கருவியையும் போலவே, இணையம் தணிக்கை, கண்காணிப்பு, தாக்குதல்கள் மற்றும் முயற்சிகள் ஆகியவற்றிலிருந்து விடுபடவில்லை, இது மாநில நடிகர்கள் மற்றும் குற்றவியல் குழுக்களின் மனக்குறை குரல்களை ம silence னமாக்குகிறது. சனநாயக வெளிப்பாடு குற்றவாளியாக இருக்கும்போது, இன மற்றும் அரசியல் பாகுபாடு இருக்கும்போது, வன்முறையற்ற எதிர்ப்பிற்கான இணையம் மற்றொரு போர்க்களமாக மாறும்",
    ),
    "messageEqValuesP4": MessageLookupByLibrary.simpleMessage(
      "ஆன்லைனில் இலவச தகவல்களின் ஓட்டம் உள்ளிட்ட அடிப்படை சுதந்திரங்கள் மற்றும் மனித உரிமைகளை ஊக்குவிப்பதும் பாதுகாப்பதும் எங்கள் நோக்கம். அணுகக்கூடிய தொழில்நுட்பத்தை உருவாக்குவதும், டிசிட்டல் யுகத்தில் மனித உரிமைகள் மற்றும் சுதந்திரங்களை பாதுகாப்பதற்குத் தேவையான திறன் தொகுப்பை மேம்படுத்துவதும் எங்கள் குறிக்கோள்",
    ),
    "messageEqValuesP5": MessageLookupByLibrary.simpleMessage(
      "டிசிட்டல் களத்தில் பாதுகாப்பான செயல்பாடுகளை அனுபவிப்பதற்கான எங்கள் அங்கத்தினர்களின் திறனைப் பயிற்றுவிப்பதையும் உயர்த்துவதையும் நாங்கள் நோக்கமாகக் கொண்டுள்ளோம். சுதந்திரமான வெளிப்பாட்டை செயல்படுத்தும் மற்றும் பாதுகாக்கும், தணிக்கை செய்வதைத் தவிர்த்து, அநாமதேயத்தை மேம்படுத்துதல் மற்றும் தேவைப்படும் போது கண்காணிப்பிலிருந்து பாதுகாக்கும் கருவிகளை உருவாக்குவதன் மூலம் இதைச் செய்கிறோம். எங்கள் கருவிகள் செய்தி மேலாண்மை மற்றும் பகுப்பாய்வு செயல்பாடுகளையும் மேம்படுத்துகின்றன",
    ),
    "messageEqValuesP6": MessageLookupByLibrary.simpleMessage(
      "நாங்கள் மாறுபட்ட பின்னணிகள் மற்றும் நம்பிக்கைகளைச் சேர்ந்த ஆர்வலர்களின் பன்னாட்டு குழு, நம்மிடையே பொதுவான கொள்கைகளை பாதுகாக்க ஒன்றாக நிற்கிறோம். நாங்கள் மென்பொருள் உருவாக்குநர்கள், கிரிப்டோகிராஃபர்கள், பாதுகாப்பு வல்லுநர்கள், அத்துடன் கல்வியாளர்கள், சமூகவியலாளர்கள், வரலாற்றாசிரியர்கள், மானுடவியலாளர்கள் மற்றும் பத்திரிகையாளர்கள். தனியுரிமை, நிகழ்நிலை பாதுகாப்பு மற்றும் சிறந்த செய்தி நிர்வாகத்தை மையமாகக் கொண்டு திறந்த மற்றும் மறுபயன்பாட்டு கருவிகளை நாங்கள் உருவாக்குகிறோம். எங்கள் செயல்பாடுகளுக்கு பொது மானியங்கள் மற்றும் ஆலோசனைகளுடன் தனியார் துறையுடன் நிதியளிக்கிறோம். ஊடுருவும் மற்றும் நியாயப்படுத்தப்படாத கண்காணிப்பு, தணிக்கை மற்றும் அடக்குமுறை ஆகியவற்றிலிருந்து விடுபட்ட இணையத்தை நாங்கள் நம்புகிறோம்",
    ),
    "messageEqValuesP7": MessageLookupByLibrary.simpleMessage(
      "மனித உரிமைகளின் பன்னாட்டு மசோதாவால் ஈர்க்கப்பட்டு, நாங்கள் வெளியிடும் மென்பொருள் மற்றும் சேவைகளின் பயனாளிகள் உட்பட, நாங்கள் பணிபுரியும் சமூகத்தின் ஒவ்வொரு தனிநபர், குழு மற்றும் உறுப்புக்கும் எங்கள் கொள்கைகள் பொருந்தும். எங்கள் திட்டங்கள் அனைத்தும் எங்கள் கொள்கைகளை மனதில் கொண்டு வடிவமைக்கப்பட்டுள்ளன. எங்கள் கொள்கைகள் மற்றும் பணி விதிமுறைகள் மதிக்கப்படும் வரை எங்கள் அறிவு, கருவிகள் மற்றும் சேவைகள் இந்த குழுக்களுக்கும் தனிநபர்களுக்கும் கிடைக்கின்றன",
    ),
    "messageEqValuesP8": MessageLookupByLibrary.simpleMessage(
      "தனியுரிமைக்கான உரிமை என்பது ஒரு அடிப்படை உரிமையாகும், இது எப்போது வேண்டுமானாலும் எங்கு வேண்டுமானாலும் பாதுகாப்பதை நோக்கமாகக் கொண்டுள்ளது. எங்கள் நேரடி பயனாளிகளின் தனியுரிமை எங்கள் செயல்பாடுகளுக்கு புனிதமானது. எங்கள் கருவிகள், சேவைகள் மற்றும் உள் கொள்கைகள் இந்த விளைவுக்காக வடிவமைக்கப்பட்டுள்ளன. எங்கள் பயனாளிகளின் தனியுரிமையைப் பாதுகாக்க அனைத்து தொழில்நுட்ப மற்றும் சட்ட ஆதாரங்களையும் எங்கள் வசம் பயன்படுத்துவோம். எங்கள் தனியுரிமைக் கொள்கையையும் எங்கள் தனியுரிமைக் கொள்கையையும் பார்க்கவும் ",
    ),
    "messageEqValuesP9": MessageLookupByLibrary.simpleMessage(
      "எங்கள் மென்பொருள் மேம்பாடு, பணி வழங்கல் மற்றும் திறன் மேம்பாட்டு திட்டங்கள் அனைத்திலும் பாதுகாப்பு ஒரு நிலையான கருப்பொருள் ஆகும். இணையத்தில் செய்தி பாதுகாப்பை மேம்படுத்தவும் பயனரின் பாதுகாப்பு சுயவிவரம் மற்றும் அனுபவத்தை உயர்த்தவும் எங்கள் அமைப்புகள் மற்றும் செயல்முறைகளை நாங்கள் வடிவமைக்கிறோம். விரைவு, பயன்பாட்டினை அல்லது செலவு பொருட்டு ஒரு கருவி அல்லது அமைப்பின் பாதுகாப்பு பண்புகளை வேறுபாடின்மை செய்யாததன் மூலம் எடுத்துக்காட்டாக வழிநடத்த முயற்சிக்கிறோம். தெளிவின்மை மூலம் பாதுகாப்பை நாங்கள் நம்பவில்லை, எங்கள் குறியீடு தளத்திற்கு திறந்த அணுகல் மூலம் வெளிப்படைத்தன்மையை பராமரிக்கிறோம். நாங்கள் எப்போதும் எச்சரிக்கையின் பக்கத்தில் தவறு செய்கிறோம், நல்ல உள் செயல்பாட்டு பாதுகாப்பை செயல்படுத்த முயற்சிக்கிறோம்",
