    ),
    "messageSecurityPracticesP3": MessageLookupByLibrary.simpleMessage(
      "OUISYNC பயன்பாடு பயனர்களின் தரவை கனடாவில் அமைந்துள்ள ஒரு சேவையகமான \'எப்போதும்-ஆன் பியர்\' இல் சேமிக்கிறது. எல்லா தரவுகளும் மறைகுறியாக்கப்பட்ட துகள்களாக சேமிக்கப்படுகின்றன, மேலும் அவை சேவையகம் அல்லது அதன் ஆபரேட்டர்களால் படிக்க முடியாது. இந்த சேவையகத்தின் நோக்கம் ஒரே நேரத்தில் ஆன்லைனில் இல்லாத சகாக்களுக்கு இடையிலான இடைவெளிகளைக் குறைப்பதாகும். எல்லா தரவுகளும் இந்த சேவையகத்திலிருந்து அவ்வப்போது சுத்திகரிக்கப்படுகின்றன - அதன் நோக்கம் நிரந்தர தரவு சேமிப்பகத்தை வழங்குவதல்ல, ஆனால் சகாக்களால் தரவு ஒத்திசைவை எளிதாக்குவது",
    ),
    "messageSecurityPracticesP4": MessageLookupByLibrary.simpleMessage(
