    ),
    "messageTerms1_1": MessageLookupByLibrary.simpleMessage(
      "அடிப்படை மதிப்புகள் அல்லது கடிதம் உள்ளிட்ட தனிப்பட்ட செய்தி பாதுகாப்பு உரிமைகளை மீறுகிறது ",
    ),
    "messageTerms1_2": MessageLookupByLibrary.simpleMessage(
      "(தனிப்பட்ட செய்தி பாதுகாப்பு மற்றும் மின்னணு ஆவணங்கள் சட்டம்)",
    ),
    "messageTerms2": MessageLookupByLibrary.simpleMessage(
      "குழந்தை பாலியல் சுரண்டல் பொருள் (சட்டவிரோத குழந்தை பாலியல் துச்பிரயோகப் பொருளாக இல்லாத பொருள் உட்பட, ஆனால் சிறார்களின் பாலியல் சுரண்டலை பாலியல் சுரண்டல் அல்லது ஊக்குவிக்கிறது), சட்டவிரோத ஆபாசப் படங்கள், அல்லது வேறுவிதமாக அநாகரீகமானவை",
    ),
    "messageTerms3": MessageLookupByLibrary.simpleMessage(
      "பயங்கரவாதம் அல்லது வன்முறை தீவிரவாத பிரச்சாரம் உள்ளிட்ட வன்முறை அல்லது பயங்கரவாத நடவடிக்கைகளின் தீவிர செயல்களைக் கொண்டுள்ளது அல்லது ஊக்குவிக்கிறது",
    ),
    "messageTerms4": MessageLookupByLibrary.simpleMessage(
      "மதவெறி, வெறுப்பு, அல்லது எந்தவொரு நபர் அல்லது குழுவினருக்கு எதிராக வன்முறையைத் தூண்டுவதை ஆதரிக்கிறது, அவர்களின் இனம், மதம், இனம், தேசிய தோற்றம், பாலினம், பாலின அடையாளம், பாலியல் நோக்குநிலை, இயலாமை, குறைபாடு அல்லது தொடர்புடைய வேறு எந்த சிறப்பியல்பு (கள்) முறையான பாகுபாடு அல்லது ஓரங்கட்டல்",
    ),
    "messageTerms5": MessageLookupByLibrary.simpleMessage(
      "வைரச்கள், ட்ரோசான்கள், புழுக்கள், வழக்கு வெடிகுண்டுகள் அல்லது தீங்கிழைக்கும் அல்லது தொழில்நுட்ப ரீதியாக தீங்கு விளைவிக்கும் பிற பொருள்களைக் கொண்ட கோப்புகள்",
    ),
    "messageTermsPrivacyP1": MessageLookupByLibrary.simpleMessage(
      "இந்த Ouisync பயன்பாட்டு விதிமுறைகள் (“ஒப்பந்தம்”), எங்கள் தனியுரிமை அறிவிப்புடன் (கூட்டாக, “விதிமுறைகள்”), உங்கள் பயன்பாட்டைப் பயன்படுத்துவதை நிர்வகிக்கின்றன - நிகழ்நிலை கோப்பு ஒத்திசைவு நெறிமுறை மற்றும் மென்பொருள்.",
    ),
    "messageTermsPrivacyP2": MessageLookupByLibrary.simpleMessage(
      "OUISYNC பயன்பாட்டை நிறுவி இயக்குவதன் மூலம், உங்களுக்கும் EMEATITIE INC க்கும் இடையிலான இந்த ஒப்பந்தத்திற்கு இணங்கவும் உங்கள் ஒப்புதலைக் குறிக்கிறது. (“சமநிலை”, “நாங்கள்” அல்லது “எங்களுக்கு”). OUISYNC பயன்பாடு மற்றும் OUISYNC பிணையம் (சேவை) ஆகியவற்றின் பயன்பாடு ஈக்விட்டியால் எந்த செலவும் இல்லாமல் வழங்கப்படுகிறது, மேலும் இது பயன்படுத்தப்பட வேண்டும்",
    ),
    "messageTermsPrivacyP3": MessageLookupByLibrary.simpleMessage(
      "OUISYNC பயன்பாடு ஈக்விட்டியின் மதிப்புகளுடன் வரிசையில் கட்டப்பட்டுள்ளது. இந்த மென்பொருளைப் பயன்படுத்துவதன் மூலம், அடிப்படை மதிப்புகள் அல்லது கியூபெக் அல்லது கனடாவின் சட்டங்களின் கடிதம் அல்லது மனித உரிமைகள் பன்னாட்டு மசோதா ஆகியவற்றுக்கு முரணான பொருட்களை வெளியிட, பகிர்ந்து கொள்ள அல்லது சேமிக்க நீங்கள் OUISYNC ஐப் பயன்படுத்த மாட்டீர்கள் என்பதை ஒப்புக்கொள்கிறீர்கள், இதில் உள்ளடக்கம் அடங்கும்:",
